import type { GuidanceDocument } from '../types/guidance';
import type { WorkerSelection } from '../types/change-request-types';
import type {
  ProjectContext,
  StartVariantsBriefContent,
  Target,
  WorkerFidelity,
} from './contracts';
import type { RequestWorkResult } from './SessionStore';

export interface VariantStartRequest {
  previewRoutes?: string[];
  beforeDispatch?: (workItemIds: string[]) => Promise<void> | void;
  guidance?: GuidanceDocument[];
  assertContext?: () => void;
  prompt: string;
  count?: number;
  target?: Target;
  projectContext?: ProjectContext;
  sessionId?: string;
  runLabel?: string;
  leaseOwner?: string;
  briefs?: StartVariantsBriefContent[];
  requestId?: string;
  allowAccumulate?: boolean;
  sourceVariantId?: string;
  profileReferenceMode?: 'inherit' | 'replace';
  relevantFiles?: string[];
  sourceReferences?: string[];
  fidelity?: WorkerFidelity;
  workerSelection?: WorkerSelection;
}

export interface VariantStartResult {
  sessionId: string;
  variants: Array<{
    variantId: string;
    briefId: string;
    label: string;
    status: 'pending';
  }>;
  scaffoldBaseWorkItemId: string | null;
  leaseId?: string;
  leaseTtlMs?: number;
  leasedWorkItems?: RequestWorkResult['leasedWorkItems'];
}
